#![allow(clippy::excessive_precision)]

use thermopack_rs::chain_rule::{
    PackingFractionDerivatives, TermDerivatives, convert_zeta_x_to_tvn,
};

const ATOL: f64 = 1.0e-15;
const RTOL: f64 = 1.0e-13;

fn zeta() -> PackingFractionDerivatives {
    PackingFractionDerivatives {
        value: 0.1,
        temperature: -0.2,
        temperature_second: 0.3,
        volume: -0.4,
        volume_second: 0.5,
        volume_third: 0.0,
        temperature_volume: 0.6,
        volume_temperature_second: 0.0,
        volume_temperature_third: 0.0,
        moles: vec![-0.7, 0.8],
        moles_second: vec![0.9, -1.1, 1.2, -1.3],
        temperature_moles: vec![0.0, 0.0],
        volume_moles: vec![0.0, 0.0],
        volume_moles_second: vec![0.0; 4],
        volume_temperature_moles: vec![0.0, 0.0],
    }
}

fn term() -> TermDerivatives {
    TermDerivatives {
        value: 2.0,
        packing_fraction: 0.25,
        reduced_distance: -0.35,
        packing_fraction_second: 0.45,
        reduced_distance_second: -0.55,
        packing_fraction_reduced_distance: 0.65,
        packing_fraction_third: -0.75,
        packing_fraction_second_reduced_distance: 0.85,
        packing_fraction_reduced_distance_second: -0.95,
    }
}

#[test]
fn the_chain_rule_matches_the_source() {
    let source: Vec<f64> = include_str!("fixtures/chain_rule.csv")
        .lines()
        .nth(1)
        .expect("fixture row")
        .split(';')
        .skip(1)
        .map(|value| value.parse().unwrap())
        .collect();
    let result = convert_zeta_x_to_tvn(&term(), 0.3, 0.15, -0.25, &zeta(), 2);
    let native = [
        result.temperature,
        result.volume,
        result.moles[0],
        result.moles[1],
        result.temperature_second,
        result.volume_second,
        result.temperature_volume,
        result.temperature_moles[0],
        result.temperature_moles[1],
        result.volume_moles[0],
        result.volume_moles[1],
        result.moles_second[0],
        result.moles_second[1],
        result.moles_second[2],
        result.moles_second[3],
    ];
    assert_eq!(native.len(), source.len());
    for (position, (source, native)) in source.iter().zip(native.iter()).enumerate() {
        assert!(
            (source - native).abs() <= ATOL + RTOL * source.abs(),
            "entry {position}: source {source} native {native}"
        );
    }
}

#[test]
fn the_level_selects_the_order_of_the_derivatives() {
    // The first level gives the first derivatives only.
    let first = convert_zeta_x_to_tvn(&term(), 0.3, 0.15, -0.25, &zeta(), 1);
    assert!(first.temperature_second == 0.0);
    assert!(first.volume_second == 0.0);
    assert!(first.temperature != 0.0);
    // The third level adds the third derivatives.
    let third = convert_zeta_x_to_tvn(&term(), 0.3, 0.15, -0.25, &zeta(), 3);
    assert!(third.volume_third != 0.0);
    assert!(third.temperature_second != 0.0);
}
